import{_ as p,a0 as i,w as a,s as l,ao as u,I as s,x as o,a1 as e,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux 有問必答：如何在 Linux 中統計一個進程的線程數 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何在 Linux 中統計一個進程的線程數 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何在 Linux 中統計一個進程的線程數 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何在 Linux 中統計一個進程的線程數 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150817 Linux FAQs with Answers--How to count the number of threads in a process on Linux","title":"Linux 有問必答：如何在 Linux 中統計一個進程的線程數","tag":"201509","desc":""},"relativePath":"201509/20150817 Linux FAQs with Answers--How to count the number of threads in a process on Linux.md","filePath":"[post].md"}'),d={name:"201509/20150817 Linux FAQs with Answers--How to count the number of threads in a process on Linux.md"};function x(m,t,f,L,g,h){const n=i("Link");return a(),l("div",null,[t[16]||(t[16]=u(`<h1 id="linux-有問必答-如何在-linux-中統計一個進程的線程數" tabindex="-1">Linux 有問必答：如何在 Linux 中統計一個進程的線程數 <a class="header-anchor" href="#linux-有問必答-如何在-linux-中統計一個進程的線程數" aria-label="Permalink to “Linux 有問必答：如何在 Linux 中統計一個進程的線程數”">​</a></h1><blockquote><p><strong>問題</strong>: 我正在運行一個程序，它在運行時會派生出多個線程。我想知道程序在運行時會有多少線程。在 Linux 中檢查進程的線程數最簡單的方法是什麼？</p></blockquote><p>如果你想看到 Linux 中每個進程的線程數，有以下幾種方法可以做到這一點。</p><h3 id="方法一-proc" tabindex="-1">方法一: /proc <a class="header-anchor" href="#方法一-proc" aria-label="Permalink to “方法一: /proc”">​</a></h3><p>proc 偽文件系統，它駐留在 /proc 目錄，這是最簡單的方法來查看任何活動進程的線程數。 /proc 目錄以可讀文本文件形式輸出，提供現有進程和系統硬件相關的信息如 CPU、中斷、內存、磁盤等等.</p><pre><code>$ cat /proc/&lt;pid&gt;/status
</code></pre><p>上面的命令將顯示進程 <code>&lt;pid&gt;</code> 的詳細信息，包括過程狀態（例如, sleeping, running)，父進程 PID，UID，GID，使用的文件描述符的數量，以及上下文切換的數量。輸出也包括<strong>進程創建的總線程數</strong>如下所示。</p><pre><code>Threads: &lt;N&gt;
</code></pre><p>例如，檢查 PID 20571進程的線程數：</p><pre><code>$ cat /proc/20571/status
</code></pre><p><img src="https://farm6.staticflickr.com/5649/20341236279_f4a4d809d2_b.jpg" alt=""></p><p>輸出表明該進程有28個線程。</p><p>或者，你可以在 <code>/proc/&lt;pid&gt;/task</code> 中簡單的統計子目錄的數量，如下所示。</p><pre><code>$ ls /proc/&lt;pid&gt;/task | wc
</code></pre><p>這是因為，對於一個進程中創建的每個線程，在 <code>/proc/&lt;pid&gt;/task</code> 中會創建一個相應的目錄，命名為其線程 ID。由此在 <code>/proc/&lt;pid&gt;/task</code> 中目錄的總數表示在進程中線程的數目。</p><h3 id="方法二-ps" tabindex="-1">方法二: ps <a class="header-anchor" href="#方法二-ps" aria-label="Permalink to “方法二: ps”">​</a></h3><p>如果你是功能強大的 ps 命令的忠實用户，這個命令也可以告訴你一個進程（用“H”選項）的線程數。下面的命令將輸出進程的線程數。“h”選項需要放在前面。</p><pre><code>$ ps hH p &lt;pid&gt; | wc -l
</code></pre>`,18)),s("p",null,[t[1]||(t[1]=o("如果你想監視一個進程的不同線程消耗的硬件資源（CPU & memory），請參閲",-1)),e(n,{href:"https://linux.cn/article-5633-1.html"},{default:r(()=>[...t[0]||(t[0]=[o("此教程",-1)])]),_:1}),t[2]||(t[2]=o("。",-1))]),t[17]||(t[17]=s("hr",null,null,-1)),s("p",null,[t[4]||(t[4]=o("via: ",-1)),e(n,{href:"http://ask.xmodulo.com/number-of-threads-process-linux.html"},{default:r(()=>[...t[3]||(t[3]=[o("http://ask.xmodulo.com/number-of-threads-process-linux.html",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=o("作者：",-1)),e(n,{href:"http://ask.xmodulo.com/author/nanni"},{default:r(()=>[...t[5]||(t[5]=[o("Dan Nanni",-1)])]),_:1}),t[9]||(t[9]=o(" 譯者：",-1)),e(n,{href:"https://github.com/strugglingyouth"},{default:r(()=>[...t[6]||(t[6]=[o("strugglingyouth",-1)])]),_:1}),t[10]||(t[10]=o(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[13]||(t[13]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[11]||(t[11]=[o("LCTT",-1)])]),_:1}),t[14]||(t[14]=o(" 原創翻譯，",-1)),e(n,{href:"https://linux.cn/"},{default:r(()=>[...t[12]||(t[12]=[o("Linux中國",-1)])]),_:1}),t[15]||(t[15]=o(" 榮譽推出",-1))])])}const w=p(d,[["render",x]]);export{b as __pageData,w as default};
